import { promises as fs } from "node:fs";
import { randomBytes } from "node:crypto";

const DATA_FILE = new URL("../data/books.json", import.meta.url);

async function readAll() {
  try {
    const raw = await fs.readFile(DATA_FILE, "utf8");
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed.books) ? parsed.books : [];
  } catch (err) {
    if (err.code === "ENOENT") return [];
    throw err;
  }
}

async function writeAll(books) {
  await fs.mkdir(new URL("../data/", DATA_FILE), { recursive: true });
  await fs.writeFile(DATA_FILE, JSON.stringify({ books }, null, 2));
}

function newId() {
  return randomBytes(6).toString("base64url");
}

export async function listBooks() {
  const books = await readAll();
  books.sort((a, b) => {
    if (a.status !== b.status) return a.status === "reading" ? -1 : 1;
    return new Date(b.createdAt) - new Date(a.createdAt);
  });
  return books;
}

export async function getBook(id) {
  const books = await readAll();
  return books.find((b) => b.id === id) || null;
}

export async function addBook({ title, author, notes }) {
  const books = await readAll();
  const book = {
    id: newId(),
    title: title.trim(),
    author: author.trim(),
    notes: (notes || "").trim(),
    status: "reading",
    createdAt: new Date().toISOString(),
    finishedAt: null,
  };
  books.push(book);
  await writeAll(books);
  return book;
}

export async function markFinished(id) {
  const books = await readAll();
  const book = books.find((b) => b.id === id);
  if (!book) return null;
  book.status = "finished";
  book.finishedAt = new Date().toISOString();
  await writeAll(books);
  return book;
}

export async function updateNotes(id, notes) {
  const books = await readAll();
  const book = books.find((b) => b.id === id);
  if (!book) return null;
  book.notes = (notes || "").trim();
  await writeAll(books);
  return book;
}

