import express from "express";
import {
  listBooks,
  getBook,
  addBook,
  markFinished,
  updateNotes,
} from "./storage.js";

const app = express();
app.use(express.urlencoded({ extended: false }));

const esc = (s) =>
  String(s ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");

const layout = (title, body) => `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(title)} · Books</title>
<style>
  :root { color-scheme: light dark; }
  body { font-family: system-ui, -apple-system, sans-serif; max-width: 720px; margin: 2rem auto; padding: 0 1rem; line-height: 1.5; }
  h1 { margin: 0 0 0.25rem; }
  .subtitle { color: #777; margin-bottom: 2rem; }
  h2 { margin-top: 2rem; border-bottom: 1px solid #ddd; padding-bottom: 0.25rem; }
  ul.books { list-style: none; padding: 0; }
  ul.books li { padding: 0.5rem 0; border-bottom: 1px solid #eee; display: flex; justify-content: space-between; align-items: baseline; gap: 1rem; }
  ul.books a { color: inherit; text-decoration: none; }
  ul.books a:hover { text-decoration: underline; }
  .author { color: #777; font-size: 0.9rem; }
  .empty { color: #777; font-style: italic; }
  form { display: grid; gap: 0.75rem; max-width: 480px; }
  label { display: grid; gap: 0.25rem; font-weight: 500; }
  input, textarea { padding: 0.5rem; border: 1px solid #ccc; border-radius: 4px; font: inherit; }
  textarea { min-height: 6rem; resize: vertical; }
  button { padding: 0.5rem 1rem; border: 1px solid #444; background: #444; color: white; border-radius: 4px; cursor: pointer; font: inherit; }
  button.secondary { background: transparent; color: inherit; }
  .actions { display: flex; gap: 0.5rem; align-items: center; margin-top: 1rem; }
  a.back { display: inline-block; margin-bottom: 1rem; color: inherit; }
  .notes { white-space: pre-wrap; background: rgba(127,127,127,0.08); padding: 0.75rem; border-radius: 4px; }
  .meta { color: #777; font-size: 0.85rem; }
</style>
</head>
<body>
${body}
</body>
</html>`;

app.get("/", async (_req, res) => {
  const books = await listBooks();
  const reading = books.filter((b) => b.status === "reading");
  const finished = books.filter((b) => b.status === "finished");

  const renderItem = (b) => `
    <li>
      <a href="/books/${esc(b.id)}">${esc(b.title)}</a>
      <span class="author">${esc(b.author)}</span>
    </li>`;

  const body = `
    <h1>My Books</h1>
    <p class="subtitle"><a href="/books/new">+ Add a book</a></p>
    <h2>Currently reading (${reading.length})</h2>
    <ul class="books">
      ${reading.length ? reading.map(renderItem).join("") : `<li class="empty">Nothing here yet.</li>`}
    </ul>
    <h2>Finished (${finished.length})</h2>
    <ul class="books">
      ${finished.length ? finished.map(renderItem).join("") : `<li class="empty">No finished books yet.</li>`}
    </ul>
  `;
  res.send(layout("Home", body));
});

app.get("/books/new", (_req, res) => {
  const body = `
    <a class="back" href="/">&larr; Back</a>
    <h1>Add a book</h1>
    <form method="post" action="/books">
      <label>Title <input name="title" required autofocus></label>
      <label>Author <input name="author" required></label>
      <label>Notes <textarea name="notes" placeholder="Optional"></textarea></label>
      <div class="actions">
        <button type="submit">Save</button>
        <a class="back" href="/">Cancel</a>
      </div>
    </form>
  `;
  res.send(layout("Add a book", body));
});

app.post("/books", async (req, res) => {
  const { title, author, notes } = req.body;
  if (!title?.trim() || !author?.trim()) {
    return res.status(400).send(layout("Error", `
      <a class="back" href="/books/new">&larr; Back</a>
      <h1>Missing fields</h1>
      <p>Title and author are required.</p>
    `));
  }
  const book = await addBook({ title, author, notes });
  res.redirect(`/books/${book.id}`);
});

app.get("/books/:id", async (req, res) => {
  const book = await getBook(req.params.id);
  if (!book) {
    return res.status(404).send(layout("Not found", `
      <a class="back" href="/">&larr; Back</a>
      <h1>Book not found</h1>
    `));
  }
  const body = `
    <a class="back" href="/">&larr; Back</a>
    <h1>${esc(book.title)}</h1>
    <p class="author">by ${esc(book.author)}</p>
    <p class="meta">
      Status: ${esc(book.status)}
      ${book.finishedAt ? `· finished ${esc(new Date(book.finishedAt).toLocaleDateString())}` : ""}
    </p>

    <h2>Notes</h2>
    <form method="post" action="/books/${esc(book.id)}/notes">
      <textarea name="notes" placeholder="Your thoughts...">${esc(book.notes)}</textarea>
      <div class="actions">
        <button type="submit">Save notes</button>
      </div>
    </form>
    ${book.notes ? `<div class="notes">${esc(book.notes)}</div>` : ""}

    ${book.status === "reading" ? `
      <form method="post" action="/books/${esc(book.id)}/finish" style="margin-top: 2rem;">
        <button type="submit">Mark as finished</button>
      </form>
    ` : ""}
  `;
  res.send(layout(book.title, body));
});

app.post("/books/:id/finish", async (req, res) => {
  const book = await markFinished(req.params.id);
  if (!book) return res.status(404).send("Not found");
  res.redirect(`/books/${book.id}`);
});

app.post("/books/:id/notes", async (req, res) => {
  const book = await updateNotes(req.params.id, req.body.notes);
  if (!book) return res.status(404).send("Not found");
  res.redirect(`/books/${book.id}`);
});

const port = process.env.PORT || 3000;
app.listen(port, () => {
  console.log(`Books app running at http://localhost:${port}`);
});

