import { describe, it, expect, beforeEach } from "vitest";
import { mkdtemp, writeFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

let dataDir;
let storage;

beforeEach(async () => {
  dataDir = await mkdtemp(join(tmpdir(), "books-"));
  const dataFile = join(dataDir, "books.json");
  await writeFile(dataFile, JSON.stringify({ books: [] }));
  storage = await import("./storage.js?tmp=" + Math.random());
  storage.__setDataFile?.(dataFile);
});

describe("storage", () => {
  it("returns empty list when no data file", async () => {
    await rm(join(dataDir, "books.json"));
    const books = await storage.listBooks();
    expect(books).toEqual([]);
  });

  it("adds and retrieves a book", async () => {
    const book = await storage.addBook({ title: "Dune", author: "Frank Herbert", notes: "Epic." });
    expect(book.id).toBeTruthy();
    expect(book.status).toBe("reading");
    expect(book.title).toBe("Dune");
    const found = await storage.getBook(book.id);
    expect(found.title).toBe("Dune");
  });

  it("marks a book as finished", async () => {
    const book = await storage.addBook({ title: "1984", author: "Orwell" });
    const updated = await storage.markFinished(book.id);
    expect(updated.status).toBe("finished");
    expect(updated.finishedAt).toBeTruthy();
  });

  it("returns null for unknown id", async () => {
    expect(await storage.getBook("nope")).toBeNull();
    expect(await storage.markFinished("nope")).toBeNull();
  });

  it("updates notes", async () => {
