import { promises as fs } from "node:fs";
import { randomBytes } from "node:crypto";
import { dirname, join } from "node:path";

const DEFAULT_FILE = join(process.cwd(), "data", "books.json");

export function createStorage(dataFile = process.env.BOOKS_DATA_FILE || DEFAULT_FILE) {
  async function readAll() {
    try {
      const raw = await fs.readFile(dataFile, "utf8");
      const parsed = JSON.parse(raw);
      return Array.isArray(parsed.books) ? parsed.books : [];
    } catch (err) {
      if (err.code === "ENOENT") return [];
      throw err;
    }
  }

  async function writeAll(books) {
    await fs.mkdir(dirname(dataFile), { recursive: true });
    await fs.writeFile(dataFile, JSON.stringify({ books }, null, 2));
  }

  function newId() {
    return randomBytes(6).toString("base64url");
  }

  async function listBooks() {
    const books = await readAll();
    books.sort((a, b) => {
      if (a.status !== b.status) return a.status === "reading" ? -1 : 1;
      return new Date(b.createdAt) - new Date(a.createdAt);
    });
    return books;
  }

  async function getBook(id) {
    const books = await readAll();
    return books.find((b) => b.id === id) || null;
  }

  async function addBook({ title, author, notes }) {
    const books = await readAll();
    const book = {
      id: newId(),
      title: title.trim(),
      author: author.trim(),
      notes: (notes || "").trim(),
      status: "reading",
      createdAt: new Date().toISOString(),
      finishedAt: null,
    };
    books.push(book);
    await writeAll(books);
    return book;
  }

  async function markFinished(id) {
    const books = await readAll();
    const book = books.find((b) => b.id === id);
    if (!book) return null;
    book.status = "finished";
    book.finishedAt = new Date().toISOString();
    await writeAll(books);
    return book;
  }

  async function updateNotes(id, notes) {
    const books = await readAll();
    const book = books.find((b) => b.id === id);
    if (!book) return null;
    book.notes = (notes || "").trim();
    await writeAll(books);
    return book;
  }

  return { listBooks, getBook, addBook, markFinished, updateNotes };
}

const defaultStorage = createStorage();
export const listBooks = defaultStorage.listBooks;
export const getBook = defaultStorage.getBook;
export const addBook = defaultStorage.addBook;
export const markFinished = defaultStorage.markFinished;
export const updateNotes = defaultStorage.updateNotes;

